import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"AI-LLM real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/ai-llm-real-driver-testing.md","filePath":"concepts/ai-llm-real-driver-testing.md"}'),r={name:"concepts/ai-llm-real-driver-testing.md"};function i(c,e,n,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="ai-llm-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" tabindex="-1">AI-LLM real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#ai-llm-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;AI-LLM real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.38-1 ai-llm package upgrade (<code>@kiwa-lab/ai-llm</code> v0.4) covers <strong>8 axes</strong> that model the surface every non-trivial production LLM stack has to reason about — prompt injection defense + hallucination detection + LLM eval + guardrails + advanced RAG + agent orchestration + fine-tuning eval + cost / latency SLA. This concept doc is the SSOT for those 8 axes; the tutorials (79-81) and dogfood apps (v1.38-2/3/4) are the concrete implementations.</p><h2 id="the-8-axis-grid" tabindex="-1">The 8-axis grid <a class="header-anchor" href="#the-8-axis-grid" aria-label="Permalink to &quot;The 8-axis grid&quot;">​</a></h2><p>The 8 axes are cover-oriented — each one names a real-world failure surface every non-trivial production LLM stack hits within the first quarter.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.4 API</th></tr></thead><tbody><tr><td>Prompt injection</td><td>&quot;The jailbreak classifier fired on <code>DAN mode</code> in the input but the Constitutional guardrail let a <code>bomb recipe</code> output through because the two checks were never chained on the same session&quot; (no 5-class classifier, no per-kind block step, no provider-neutral audit event)</td><td><code>startInjectionSession</code> / <code>detectInjection</code> / <code>classifyDirect</code> / <code>classifyIndirect</code> / <code>blockJailbreak</code> / <code>blockRoleHijacking</code></td></tr><tr><td>Hallucination</td><td>&quot;The factuality score said 0.9 but 3 of the 5 citations pointed to URLs the model hallucinated because the citation-verifier was never chained after <code>checkFactuality</code>&quot; (no self-consistency floor, no corpus-membership check, no confidence hedging scorer)</td><td><code>startHallucinationSession</code> / <code>scoreSelfConsistency</code> / <code>checkFactuality</code> / <code>verifyCitation</code> / <code>scoreConfidence</code></td></tr><tr><td>LLM eval</td><td>&quot;The LLM-as-judge picked a candidate that mirrored the prompt tokens but had zero ground-truth overlap because the rubric was never layered on top&quot; (no weighted-rubric scorer, no preference-pair aggregator, no Elo persistence)</td><td><code>startEvalSession</code> / <code>judgeCandidates</code> / <code>applyRubric</code> / <code>rankPreference</code> / <code>updateElo</code></td></tr><tr><td>Guardrails</td><td>&quot;The regex allow-list caught the injection payload but the JSON schema validator let a malformed output through because the two guardrails ran on different sessions&quot; (no session-chained guardrail state machine, no PII redactor, no Constitutional AI check)</td><td><code>startGuardrailSession</code> / <code>validateSchema</code> / <code>matchRegex</code> / <code>blockToxicity</code> / <code>redactPii</code> / <code>checkConstitutional</code></td></tr><tr><td>RAG advanced</td><td>&quot;The hybrid retriever returned the right 10 chunks but the reranker never fired because the harness assumed the sparse score alone was the ranking signal&quot; (no chunk overlap, no dense + sparse fusion, no context compressor)</td><td><code>startRagSession</code> / <code>chunkDocument</code> / <code>hybridRetrieve</code> / <code>rerank</code> / <code>compressContext</code></td></tr><tr><td>Agent orchestration</td><td>&quot;The ReAct loop stepped 20 times before the budget check fired because <code>checkBudget</code> was called after <code>reactStep</code> instead of before&quot; (no ReAct trace persistence, no ToT branching, no reflection cycle bound, no intent-scored tool router)</td><td><code>startAgentSession</code> / <code>reactStep</code> / <code>expandToT</code> / <code>reflectAndCorrect</code> / <code>selectTool</code></td></tr><tr><td>Fine-tuning eval</td><td>&quot;The DPO benchmark said preference accuracy 92 % but catastrophic forgetting on a legacy eval jumped 8 points because the two eval passes ran on different runs&quot; (no SFT F1 / exact-match scorer, no DPO log-probability margin, no baseline seeded before drift detection)</td><td><code>startFtSession</code> / <code>evaluateSft</code> / <code>evaluateDpo</code> / <code>detectCatastrophicForgetting</code> / <code>detectBenchmarkDrift</code></td></tr><tr><td>Cost / latency SLA</td><td>&quot;The model router picked the cheapest candidate but latency blew past the SLA because the quality floor was set to 0.5 instead of 0.85&quot; (no per-request cost tracker, no percentile latency, no SLA + quality-floor filter, no fallback ladder)</td><td><code>startSlaSession</code> / <code>checkBudget</code> / <code>measureLatency</code> / <code>routeModel</code> / <code>engageFallback</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real Anthropic Messages / OpenAI Chat Completions / Vercel AI SDK / LangChain, seconds scale), and a fidelity assertion that the two produce the same event stream. Tutorial 79 covers the prompt-injection + guardrails end-to-end chain (5-class detection → narrow classify → jailbreak / role-hijack block → Constitutional + PII redaction), tutorial 80 covers the hallucination + eval axes (self-consistency → factuality → citation → judge → rubric → preference → Elo), tutorial 81 covers the agent-orchestration + SLA axes (ReAct → ToT → reflection → tool selection → budget → latency → routing → fallback).</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across Anthropic Messages + OpenAI Chat Completions + Vercel AI SDK + LangChain), the emitted event dialects are provider-specific (<code>anthropic.injection.direct_detected</code> vs. <code>openai.injection.direct_detected</code> vs. <code>vercel-ai.injection.direct_detected</code> vs. <code>langchain.injection.direct_detected</code>), and the fidelity harness reports the coverage explicitly through <code>AI_LLM_AXIS_TO_EVENTS</code> + <code>collectFidelityCoverage()</code>.</p><table tabindex="0"><thead><tr><th>Provider</th><th>Prompt injection</th><th>Hallucination</th><th>LLM eval</th><th>Guardrails</th><th>RAG advanced</th><th>Agent orch</th><th>Fine-tuning eval</th><th>Cost / latency SLA</th></tr></thead><tbody><tr><td>anthropic</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>openai</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>vercel-ai</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>langchain</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v1.38 ai-llm grid is fully covered — every provider implements every axis because the semantics are backend-agnostic. That is what makes cross-provider reuse (a mock injection classifier that runs against Anthropic + OpenAI + Vercel AI + LangChain without change) even possible.</p><h3 id="why-the-ai-llm-grid-is-fully-covered" tabindex="-1">Why the ai-llm grid is fully covered <a class="header-anchor" href="#why-the-ai-llm-grid-is-fully-covered" aria-label="Permalink to &quot;Why the ai-llm grid is fully covered&quot;">​</a></h3><p>Anthropic Messages + OpenAI Chat Completions + Vercel AI SDK + LangChain converged on the same neutral events at the &quot;take a prompt, produce a completion, emit a per-step trace&quot; primitive — the &quot;LLM call over a chat-shaped payload&quot; shape is the same across all 4 providers, even though the wire encodings differ (Messages API blocks vs. Chat Completions choices vs. <code>generateText</code> result vs. LangChain runnable). The <code>providerEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.38 fidelity coverage at 32/32 = 100 % implemented reflects that convergence at the &quot;LLM call&quot; level.</p><h2 id="the-kiwa-mode-real-env-gate-contract" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract&quot;">​</a></h2><p><code>skipUnlessReal(env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real detected&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and <code>{ skip: true, reason: &#39;KIWA_MODE!=real — skip real-driver tests (mock semantics apply)&#39; }</code> otherwise. A test that respects the contract combines the gate with a per-backend <code>_API_KEY</code> presence check plus a <code>KIWA_LLM_BUDGET_USD</code> budget guard — the dogfood apps use this at each <code>describe.skipIf(gate.skip)</code> block.</p><p>Per-backend required-env mapping.</p><ul><li><strong>anthropic</strong> → <code>KIWA_MODE</code> + <code>ANTHROPIC_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (Anthropic Messages API; endpoint <code>KIWA_ANTHROPIC_URL</code> optional)</li><li><strong>openai</strong> → <code>KIWA_MODE</code> + <code>OPENAI_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (OpenAI Chat Completions API; endpoint <code>KIWA_OPENAI_URL</code> optional)</li><li><strong>vercel-ai</strong> → <code>KIWA_MODE</code> + <code>OPENAI_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (Vercel AI SDK routes through OpenAI by default; endpoint <code>KIWA_VERCEL_AI_URL</code> optional)</li><li><strong>langchain</strong> → <code>KIWA_MODE</code> + <code>OPENAI_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> (LangChain routes through OpenAI by default; endpoint <code>KIWA_LANGCHAIN_URL</code> optional)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when <code>KIWA_MODE=real</code> + the required <code>_API_KEY</code> are present and the budget guard is set. That means the fast inner loop stays cheap by default (mock only, ms scale), the nightly job flips <code>KIWA_MODE=real</code> + the required <code>_API_KEY</code> + a bounded <code>KIWA_LLM_BUDGET_USD</code>, and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode — the test still runs, the real-driver assertions get skipped. Absent <code>KIWA_MODE</code> means fall back to mock. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code>) also falls back to mock so a typo does not break tests. The budget guard (<code>resolveBudgetGuard(env)</code>) reads <code>KIWA_LLM_BUDGET_USD</code> (default <code>5.0</code>) + <code>KIWA_LLM_PER_CALL_CAP_USD</code> (default <code>0.5</code>) and refuses to charge beyond either cap.</p><h2 id="the-dogfood-app-new-pattern" tabindex="-1">The dogfood app new pattern <a class="header-anchor" href="#the-dogfood-app-new-pattern" aria-label="Permalink to &quot;The dogfood app new pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.38-2/3/4) each expose a <code>pnpm test</code> command that keeps the mock-only path green sub-second, and are wired for real-driver runs when <code>KIWA_MODE=real</code> + <code>ANTHROPIC_API_KEY</code> / <code>OPENAI_API_KEY</code> + <code>KIWA_LLM_BUDGET_USD</code> are present.</p><ul><li><code>examples/dogfood-llm-prompt-injection-defense-app</code> — Anthropic Messages + prompt injection + jailbreak + guardrails + Constitutional AI + 5-class classifier + PII redaction pipeline. Walks the defense chain (detect → classify → block → guard) against a real Anthropic Messages endpoint. 109 test.</li><li><code>examples/dogfood-llm-hallucination-eval-app</code> — OpenAI Chat Completions + LLM-as-judge + rubric-based eval + citation grounding + self-consistency + factuality + preference + Elo pipeline. Walks the eval chain against a real OpenAI Chat Completions endpoint. 90 test.</li><li><code>examples/dogfood-llm-agent-orchestration-app</code> — Vercel AI SDK + ReAct + Tree of Thoughts + reflection + tool selection + budget + latency + routing + fallback pipeline. Walks the orchestration chain against a real Vercel AI SDK <code>generateText</code> endpoint. 89 test.</li></ul><p>The pattern each new app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:real</code> command that requires <code>KIWA_MODE=real</code> + the backend-specific <code>_API_KEY</code> + a bounded <code>KIWA_LLM_BUDGET_USD</code> and routes assertions through the real provider endpoint.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real provider behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li><li>Chain the budget guard (<code>resolveBudgetGuard</code> + <code>chargeBudget</code>) around every real-driver call so a runaway loop or a bad prompt does not blow the <code>$</code> cap.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 32-cell grid at v1.38 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th axis (e.g., <code>multi-agent-coordination</code> or <code>retrieval-grounded-eval</code>), it will start as <code>planned</code> for all 4 providers, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.38 does not add a 14th release-gate axis. The 8 ai-llm axes gate the ai-llm package&#39;s own tests (via <code>pnpm --filter @kiwa-lab/ai-llm test</code>) but do not surface as a per-package <code>@kiwa-lab/quality-metrics</code> axis. The reasoning — the fidelity harness is provider-shape-specific, and a package that does not export to Anthropic Messages / OpenAI Chat Completions / Vercel AI / LangChain has nothing to assert on. When a future milestone adds an <code>ai-llm.fidelity</code> axis that describes &quot;which LLM providers this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.38 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 8 ai-llm axes live in this doc. Tutorials 79-81 and the migration guide (v1.37 → v1.38) link back here for the axis SSOT.</li><li>The 4-provider × 8-axis grid is the harness&#39;s data structure. The <code>AI_LLM_AXIS_TO_EVENTS</code> + <code>collectFidelityCoverage()</code> in <code>packages/ai-llm/src/semantics/fidelity.ts</code> is the code SSOT — this doc&#39;s grid table is derived from that constant.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak), the v1.31 streaming real-driver concept doc, the v1.32 database real-driver concept doc, the v1.33 payment real-driver concept doc, the v1.34 frontend real-driver concept doc, the v1.35 observability real-driver concept doc, the v1.36 search real-driver concept doc, and the v1.37 security real-driver concept doc. All eight use the same <code>skipUnlessReal(env)</code> pattern; the ai-llm axes just add a <code>KIWA_LLM_BUDGET_USD</code> budget guard on top so a real LLM call cannot run past the <code>$</code> cap.</li></ul>',29)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
